"""Local owner-review index, with evidence scope and missing deliverables visible."""
import json, html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]; ART=ROOT/'artifacts/v1_closure'; REVIEW=ART/'review'
def read(p):
    return json.loads(p.read_text()) if p.exists() else {}
data={'assets':read(REVIEW/'asset_manifest.json'),'baseline':read(ART/'baseline.json'),'campaign':read(ROOT/'game-godot/data/story/v1_campaign.json'),'campaign_test':read(ART/'campaign_runtime_evidence.json'),'runtime_test':read(ART/'collectible_runtime_evidence.json'),'shipping_test':read(ART/'shipping_roster_evidence.json'),'audio':read(ART/'audio_manifest.json'),'canon':read(ART/'first_loss_owner_options.json'),'identity':read(ROOT/'game-godot/data/runtime/build_identity.json'),'build':read(ART/'build_artifact.json'),'packed':read(ART/'packed_runtime_evidence.json')}
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Anime Aggressors — V1 checkpoint review</title><style>
:root{font-family:system-ui,sans-serif;color:#ecedf5;background:#10131c;color-scheme:dark}body{margin:0 auto;max-width:1450px;padding:32px}h1{font-size:38px;margin:0 0 12px}h2{margin-top:40px}p{max-width:1000px;line-height:1.6;color:#c6ccdc}.badge{display:inline-block;border:1px solid #8b7448;background:#362e1d;color:#ffe0a4;border-radius:8px;padding:8px 14px;margin:6px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:18px}.card{background:#1c2230;border:1px solid #354055;padding:16px;border-radius:12px}img{width:100%;object-fit:contain;border-radius:8px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}label{display:block;color:#b1bdd3;font-size:14px}select,button{padding:12px;border-radius:6px;background:#28344a;border:1px solid #516586;margin:0 8px 12px 0}table{border-collapse:collapse;width:100%}th,td{text-align:left;border-bottom:1px solid #354055;padding:10px;vertical-align:top}.timeline{display:flex;gap:6px;flex-wrap:wrap}.node{padding:7px 10px;border-radius:4px;background:#30384a;color:#cad0df}.node.wired{background:#214c46;color:#b7f5df}audio{width:100%;max-width:320px}.missing{color:#ffcd8d}a{color:#99d4ff}code{overflow-wrap:anywhere}details{margin:15px 0}summary{cursor:pointer}.compact img{max-height:220px}video{width:100%;max-width:800px}
</style><body><h1>Anime Aggressors</h1><p>V1 closure checkpoint • Original articulated collectible candidates • Local owner review</p><div class="badge">V1 incomplete</div><div class="badge">All seven owner gates FALSE</div><div class="badge">No publication</div><p id="identity"></p><p>Review the look, recognizability, motion and impact. These are procedural model, key-pose and SFX candidates. Model/clip counts and scripted KOs do not establish finished animation, game feel or full Story completion.</p><h2>Evidence and limits</h2><div id="evidence"></div><h2>Full roster • male / female</h2><p><a href="roster_sheet.png">Full roster sheet</a></p><div id="roster" class="grid compact"></div><h2>Base / Puppet / Prismatic / cosmic comparisons</h2><select id="fighter"></select><select id="variant"><option>male</option><option>female</option></select><div id="forms" class="grid compact"></div><h2>Real Godot camera and candidate movement</h2><p>Battle-camera captures, turntables and move demonstrations use the real Godot Compatibility renderer. Staged training actions exercise natural hitbox polling. A visible demonstration is not a complete form lifecycle test.</p><div id="runtime"></div><h2>SFX comparison</h2><p>Original filtered-noise, impulse and delay-lattice layers. Current hooks: move startup, light/heavy/special/super impact, confirmed block, KO, selection and existing form transformation. Signature, launch and Puppet/Prismatic samples still require dedicated final timing and mix integration. Audio remains unapproved.</p><select id="event"></select><div id="audio" class="grid"></div><h2>Full Story route map</h2><p>Green nodes have checkpoint runtime code. Later nodes remain blocked by implementation; six First Loss nodes also need your canon choice. Only Kaia is normally accessible until its Gray unlock. Debug route review exposes the other opening encounters without granting completion or unlocks.</p><div id="routes"></div><h2>First Loss choices — no selection made</h2><div id="canon"></div><h2>Review still required</h2><p class="missing">Complete authored motion and face/expression refinement; fighter-specific combat feel and VFX taste; every non-base form lifecycle; full Kaia and six Prismatic campaigns; Puppet teams, loss/release objectives, Essence progression, Gray transformations/endings, Sevenfold Convergence and Yin/Yang unlock; distinct Yin/Yang competitive moves; impact montage and transformation/unlock evidence; exported Web/Android runtime proof.</p><p><a href="evidence/BASELINE.md">Exact initial baseline matrix</a> · <a href="evidence/disk_cleanup.json">Exact cleanup paths and verification</a> · <a href="asset_manifest.json">Candidate asset provenance</a> · <a href="evidence/authority_lock.json">Authority lock</a> · <a href="evidence/CODEX_HANDOFF.md">Continuation handoff</a></p><script>const D=__DATA__;
const names={'ember-vale':'Ember Vale','rook-ironside':'Rook Ironside','juno-spark':'Juno Spark','kaia-windrow':'Kaia Windrow','nix-calder':'Nix Calder','orion-vell':'Orion Vell','vesper-nyx':'Vesper Nyx','yin':'Yin','yang':'Yang'};const ids=Object.keys(names);const el=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const img=(id,v,f='BASE',angle='front')=>`renders/${id}/${v}/${f}/${angle}.png`;
el('identity').innerHTML=`Source build SHA: <code>${esc(D.identity.git_sha||'Pending checkpoint commit/export stamp')}</code>`;
el('evidence').innerHTML=`<table><tr><th>Check</th><th>Result</th><th>Scope</th></tr><tr><td>Presentation generation</td><td>${D.assets.assets?.length||0}/64</td><td>Candidate geometry, skins and clips; no art approval</td></tr><tr><td>Godot model imports/playback</td><td>${D.runtime_test.ok?'PASS':'Pending / incomplete'} · ${D.runtime_test.rows?.length||0}/64</td><td>22-bone configure and embedded clips; no full battle lifecycle</td></tr><tr><td>Base shipping lifecycles</td><td>${D.shipping_test.ok?'PASS':'Pending / failed'} · ${D.shipping_test.rows?.length||0}/18</td><td>Selection, input commands, resolved contacts, scripted KOs, results/rematch</td></tr><tr><td>Opening Story encounters</td><td>${D.campaign_test.ok?'PASS':'Pending'} · ${D.campaign_test.encounters?.length||0}/49</td><td>Movement, scripted KO, battle-result receipt, save/resume; later chapters incomplete</td></tr><tr><td>Completed Gray routes / Convergence / cosmic unlock</td><td>0/7 · incomplete · locked</td><td>Not granted by structural manifests or review mode</td></tr><tr><td>SFX</td><td>${D.audio.assets?.length||0}/135 candidates</td><td>Layered original samples; SFX_MIX_HUMAN_PASS=false</td></tr></table>`;
el('evidence').innerHTML+=`<p>Exported owner-review PCK: ${D.packed.ok?'limited 9-fighter battle/input probe PASS':'runtime probe incomplete / failed'}; full exported campaigns and Web/Android remain unproved. Artifact SHA256: <code>${esc(D.build.artifact_sha256||'pending')}</code>. <a href="downloads/anime-v1-review.pck">Local owner-review PCK</a></p>`;el('roster').innerHTML=ids.map(id=>`<article class="card"><h3>${names[id]}</h3><div class="pair">${['male','female'].map(v=>`<div><label>${v}</label><img src="${img(id,v)}" alt="${names[id]} ${v} base"></div>`).join('')}</div></article>`).join('');el('fighter').innerHTML=ids.map(id=>`<option value="${id}">${names[id]}</option>`).join('');
function update(){const id=el('fighter').value,v=el('variant').value;const forms=D.assets.assets?.filter(a=>a.fighter_id===id&&a.presentation===v)||[];el('forms').innerHTML=forms.map(a=>`<article class="card"><h3>${esc(a.form.replaceAll('_',' '))}</h3><img src="${img(id,v,a.form)}" alt="${esc(a.form)}"></article>`).join('');el('runtime').innerHTML=`<div class="pair"><div><label>Shipping battle camera</label><img src="runtime/${id}/battle.png" alt="${names[id]} battle camera" onerror="this.replaceWith('Capture pending')"></div><div><label>Runtime turntable</label><img src="runtime/${id}/turntable.gif" alt="${names[id]} runtime turntable" onerror="this.replaceWith('Turntable pending')"></div></div><div class="grid compact">${['jab_1','heavy_attack','side_special','aura_burst'].map(m=>`<article class="card"><h3>${esc(m)}</h3><img src="runtime/${id}/${m}.gif" alt="${names[id]} ${m}" onerror="this.replaceWith('Demonstration pending')"></article>`).join('')}</div>`;}
el('fighter').onchange=update;el('variant').onchange=update;update();const events=['whiff','light','heavy','signature','special','super_startup','super_impact','block','launch','ko','select','transform','black_puppet','white_puppet','prismatic'];el('event').innerHTML=events.map(e=>`<option>${e}</option>`).join('');function audio(){el('audio').innerHTML=ids.map(id=>`<article class="card"><label>${names[id]}</label><audio controls preload="none" src="audio/${id}/${el('event').value}.wav"></audio></article>`).join('');}el('event').onchange=audio;audio();el('routes').innerHTML=D.campaign.routes.map(r=>`<details open><summary>${esc(r.title)} · ${r.nodes.filter(n=>n.implemented).length}/${r.nodes.length} nodes wired · route incomplete</summary><div class="timeline">${r.nodes.map(n=>`<span class="node ${n.implemented?'wired':''}" title="${esc(n.block_reason||n.objective||'Checkpoint node')}">${esc(n.title)}${n.canon_status==='OPEN_CANON'?' — OWNER CHOICE':''}</span>`).join('')}</div></details>`).join('');el('canon').innerHTML=`<p>Kaia → Rook is canonical. All six other choices remain OPEN.</p>`+Object.entries(D.canon.candidates).map(([id,options])=>`<details><summary>${names[id]}</summary><ul>${options.map(o=>`<li><b>${names[o.fighter_id]}</b>: ${esc(o.rationale)}</li>`).join('')}</ul></details>`).join('');</script></body></html>'''
REVIEW.mkdir(parents=True,exist_ok=True);(REVIEW/'index.html').write_text(page.replace('__DATA__',json.dumps(data).replace('</','<\\/')))
